CREATE TABLE `motor` (
  `id` int(10) UNSIGNED NOT NULL,
  `kode` varchar(20) NOT NULL COMMENT 'Dibentuk otomatis dari segmen akhir plat nomor',
  `model` varchar(100) NOT NULL COMMENT 'Jenis motor, tanpa keterangan warna',
  `warna` varchar(50) DEFAULT NULL,
  `plat_nomor` varchar(20) NOT NULL,
  `tarif_weekday` int(10) UNSIGNED NOT NULL COMMENT 'Tarif per 24 jam, Senin sampai Jumat',
  `tarif_weekend` int(10) UNSIGNED NOT NULL COMMENT 'Tarif per 24 jam, Sabtu dan Minggu',
  `status_override` enum('OFTR','OTRB','ONTR','Perawatan') DEFAULT NULL COMMENT 'NULL = status mengikuti hitungan otomatis',
  `spesifikasi` text DEFAULT NULL,
  `foto` longtext DEFAULT NULL COMMENT 'Foto motor dalam bentuk Base64',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Armada / unit motor';

