INSERT INTO `motor` (`id`, `kode`, `model`, `warna`, `plat_nomor`, `tarif_weekday`, `tarif_weekend`, `status_override`, `spesifikasi`, `foto`, `created_at`, `updated_at`) VALUES
(1, 'VFF', 'PCX', 'Putih', 'D 5882 VFF', 200000, 220000, NULL, 'Honda PCX merupakan skuter premium dari Honda yang dirancang untuk memberikan kenyamanan berkendara, baik di dalam kota maupun perjalanan jarak jauh. Motor ini menggunakan mesin 160 cc eSP+ berpendingin cairan yang menghasilkan tenaga sekitar 16 PS dengan torsi sekitar 14,7 Nm. Posisi duduknya lebar dan ergonomis, sehingga pengendara maupun penumpang tetap nyaman meskipun digunakan dalam waktu lama. PCX juga dilengkapi bagasi yang sangat luas, Smart Key System (keyless), USB charger, panel instrumen digital, serta rem cakram depan dan belakang dengan ABS pada beberapa tipe. Motor ini sangat cocok untuk pengguna yang mengutamakan kenyamanan, fitur modern, dan tampilan yang elegan.', 'data:image/jpeg;base64,', '2026-08-10 00:18:19', '2026-08-10 00:18:19');
INSERT INTO `motor` (`id`, `kode`, `model`, `warna`, `plat_nomor`, `tarif_weekday`, `tarif_weekend`, `status_override`, `spesifikasi`, `foto`, `created_at`, `updated_at`) VALUES
(2, 'VBC', 'PCX', 'Putih', 'D 5723 VBC', 200000, 220000, NULL, 'Honda PCX merupakan skuter premium dari Honda yang dirancang untuk memberikan kenyamanan berkendara, baik di dalam kota maupun perjalanan jarak jauh. Motor ini menggunakan mesin 160 cc eSP+ berpendingin cairan yang menghasilkan tenaga sekitar 16 PS dengan torsi sekitar 14,7 Nm. Posisi duduknya lebar dan ergonomis, sehingga pengendara maupun penumpang tetap nyaman meskipun digunakan dalam waktu lama. PCX juga dilengkapi bagasi yang sangat luas, Smart Key System (keyless), USB charger, panel instrumen digital, serta rem cakram depan dan belakang dengan ABS pada beberapa tipe. Motor ini sangat cocok untuk pengguna yang mengutamakan kenyamanan, fitur modern, dan tampilan yang elegan.', 'data:image/jpeg;base64,', '2026-08-10 00:19:19', '2026-08-10 00:19:19');
INSERT INTO `motor` (`id`, `kode`, `model`, `warna`, `plat_nomor`, `tarif_weekday`, `tarif_weekend`, `status_override`, `spesifikasi`, `foto`, `created_at`, `updated_at`) VALUES
(3, 'ABK', 'Vario 125', 'Hitam', 'D 5923 ABK', 100000, 110000, NULL, 'Honda Vario 125 merupakan salah satu motor matic paling populer di Indonesia karena terkenal irit, nyaman, dan mudah dikendarai. Motor ini menggunakan mesin 125 cc eSP berpendingin udara dengan tenaga sekitar 11 PS. Konsumsi bahan bakarnya sangat efisien sehingga cocok digunakan sebagai kendaraan harian maupun usaha rental. Vario 125 memiliki bagasi yang cukup luas, panel speedometer digital, sistem Idling Stop System (pada beberapa tipe), serta desain bodi yang sporty namun tetap ramping sehingga mudah bermanuver di jalan perkotaan.', 'data:image/jpeg;base64,', '2026-08-10 00:20:44', '2026-08-10 00:20:44');
