(38, 'MQ', 'Xeon GT', 'Putih', 'D 7282 MQ', 90000, 100000, NULL, 'Yamaha Xeon GT merupakan skuter matic berkapasitas 125 cc yang sempat dikenal karena bodinya besar dan posisi berkendaranya nyaman. Mesin injeksi Blue Core memberikan akselerasi yang cukup responsif untuk penggunaan harian. Kapasitas bagasi yang cukup besar dan jok yang lebar membuat motor ini nyaman digunakan oleh dua orang. Hingga saat ini Xeon GT masih banyak digunakan karena mesinnya terkenal tangguh.', 'data:image/jpeg;base64,', '2026-08-10 00:53:26', '2026-08-10 00:53:26');
INSERT INTO `motor` (`id`, `kode`, `model`, `warna`, `plat_nomor`, `tarif_weekday`, `tarif_weekend`, `status_override`, `spesifikasi`, `foto`, `created_at`, `updated_at`) VALUES
(39, 'OH', 'Xeon GT', 'Biru', 'D 6872 OH', 90000, 100000, NULL, 'Yamaha Xeon GT merupakan skuter matic berkapasitas 125 cc yang sempat dikenal karena bodinya besar dan posisi berkendaranya nyaman. Mesin injeksi Blue Core memberikan akselerasi yang cukup responsif untuk penggunaan harian. Kapasitas bagasi yang cukup besar dan jok yang lebar membuat motor ini nyaman digunakan oleh dua orang. Hingga saat ini Xeon GT masih banyak digunakan karena mesinnya terkenal tangguh.', 'data:image/jpeg;base64,', '2026-08-10 00:53:59', '2026-08-10 00:53:59');
INSERT INTO `motor` (`id`, `kode`, `model`, `warna`, `plat_nomor`, `tarif_weekday`, `tarif_weekend`, `status_override`, `spesifikasi`, `foto`, `created_at`, `updated_at`) VALUES
(40, 'ZBC', 'Xeon RC', 'Hitam', 'D 3808 ZBC', 85000, 100000, NULL, 'Yamaha Xeon RC merupakan penyempurnaan dari Xeon GT dengan desain yang lebih sporty dan modern. Motor ini menggunakan mesin 125 cc injeksi yang lebih halus serta dilengkapi lampu LED dan panel instrumen yang lebih menarik. Handling yang stabil dan akselerasi yang cukup baik membuat Xeon RC masih menjadi pilihan bagi pengguna yang menginginkan motor matic berukuran sedang dengan performa yang nyaman.', 'data:image/jpeg;base64,', '2026-08-10 00:55:27', '2026-08-10 00:55:27');
INSERT INTO `motor` (`id`, `kode`, `model`, `warna`, `plat_nomor`, `tarif_weekday`, `tarif_weekend`, `status_override`, `spesifikasi`, `foto`, `created_at`, `updated_at`) VALUES
(41, 'KK', 'Xeon RC', 'Biru', 'D 6910 KK', 85000, 100000, NULL, 'Yamaha Xeon RC merupakan penyempurnaan dari Xeon GT dengan desain yang lebih sporty dan modern. Motor ini menggunakan mesin 125 cc injeksi yang lebih halus serta dilengkapi lampu LED dan panel instrumen yang lebih menarik. Handling yang stabil dan akselerasi yang cukup baik membuat Xeon RC masih menjadi pilihan bagi pengguna yang menginginkan motor matic berukuran sedang dengan performa yang nyaman.', 'data:image/jpeg;base64,', '2026-08-10 00:56:07', '2026-08-10 00:56:07');
INSERT INTO `motor` (`id`, `kode`, `model`, `warna`, `plat_nomor`, `tarif_weekday`, `tarif_weekend`, `status_override`, `spesifikasi`, `foto`, `created_at`, `updated_at`) VALUES
(42, 'UFP', 'ADV', 'Merah', 'D 4662 UFP', 200000, 220000, NULL, 'Honda ADV merupakan skuter bergaya adventure yang menggabungkan kenyamanan motor matic dengan kemampuan melewati berbagai kondisi jalan. Mesin 160 cc eSP+ menghasilkan tenaga yang besar namun tetap efisien dalam konsumsi bahan bakar. ADV dilengkapi windshield yang dapat diatur, suspensi belakang tabung, ground clearance tinggi, bagasi luas, Smart Key System, panel meter digital, serta rem ABS pada tipe tertentu. Motor ini sangat cocok digunakan untuk perjalanan jauh, touring, maupun penggunaan harian dengan kenyamanan yang lebih baik dibanding skuter matic biasa.', 'data:image/jpeg;base64,', '2026-08-10 00:57:19', '2026-08-10 00:57:19');

-- --------------------------------------------------------

--
-- Struktur dari tabel `penyewaan`
--

CREATE TABLE `penyewaan` (
  `id` int(10) UNSIGNED NOT NULL,
  `nomor_sewa` varchar(20) DEFAULT NULL COMMENT 'DDMMYYHHMMSS + id admin, diisi saat konfirmasi',
  `konsumen_id` int(10) UNSIGNED NOT NULL,
  `motor_id` int(10) UNSIGNED NOT NULL,
  `tanggal_mulai` datetime NOT NULL,
  `tanggal_selesai` datetime NOT NULL COMMENT 'Tenggat berlaku, berubah bila perpanjangan disetujui',
  `tanggal_kembali_aktual` datetime DEFAULT NULL,
  `sudah_diambil` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1 = motor sudah diserahkan (OTRB -> ONTR)',
  `total_harga` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `dp_dibayar` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `denda_waktu` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `biaya_kerusakan` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `catatan_kerusakan` text DEFAULT NULL,
  `grand_total` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `metode_pembayaran` enum('Cash','TF') NOT NULL DEFAULT 'TF',
  `status_pembayaran` enum('Belum','Lunas') NOT NULL DEFAULT 'Belum',
  `metode_pengantaran` enum('Ambil di Tempat Sewa','Antar ke Alamat') NOT NULL DEFAULT 'Ambil di Tempat Sewa',
  `alamat_pengantaran` text DEFAULT NULL,
  `jarak_pengantaran` varchar(20) DEFAULT NULL COMMENT 'kurang_2km / 2_5km / lebih_5km',
  `metode_pengembalian` enum('Kembalikan ke Tempat Sewa','Jemput di Alamat') NOT NULL DEFAULT 'Kembalikan ke Tempat Sewa',
  `alamat_pengembalian` text DEFAULT NULL,
  `jarak_pengembalian` varchar(20) DEFAULT NULL COMMENT 'kurang_2km / 2_5km / lebih_5km',
  `bukti_transfer` longtext DEFAULT NULL COMMENT 'Bukti transfer DP dalam bentuk Base64',
  `status_logistik_keluar` enum('Belum di proses','Sedang di proses','Selesai di proses') NOT NULL DEFAULT 'Belum di proses',
  `status_logistik_masuk` enum('Belum di proses','Sedang di proses','Selesai di proses') NOT NULL DEFAULT 'Belum di proses',
  `status` enum('Pending','Aktif','Selesai','Ditolak') NOT NULL DEFAULT 'Pending',
  `diproses_oleh` varchar(100) DEFAULT NULL COMMENT 'Nama admin yang mengkonfirmasi',
  `dikembalikan_oleh` varchar(100) DEFAULT NULL COMMENT 'Nama admin yang memproses pengembalian',
  `perpanjangan_hari` smallint(5) UNSIGNED DEFAULT NULL,
  `perpanjangan_status` enum('Pending','Approved','Rejected') DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Penyewaan (gabungan booking + penyewaan + perpanjangan)';

