--
-- Struktur untuk view `v_laporan_bulanan`
--
DROP TABLE IF EXISTS `v_laporan_bulanan`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_laporan_bulanan`  AS SELECT date_format(`penyewaan`.`tanggal_kembali_aktual`,'%Y-%m') AS `bulan`, count(0) AS `jumlah_transaksi`, sum(`penyewaan`.`total_harga`) AS `total_sewa`, sum(`penyewaan`.`denda_waktu`) AS `total_denda`, sum(`penyewaan`.`biaya_kerusakan`) AS `total_kerusakan`, sum(`penyewaan`.`grand_total`) AS `omset` FROM `penyewaan` WHERE `penyewaan`.`status` = 'Selesai' GROUP BY date_format(`penyewaan`.`tanggal_kembali_aktual`,'%Y-%m') ORDER BY date_format(`penyewaan`.`tanggal_kembali_aktual`,'%Y-%m') DESC ;

-- --------------------------------------------------------

--
-- Struktur untuk view `v_penyewaan_detail`
--
DROP TABLE IF EXISTS `v_penyewaan_detail`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_penyewaan_detail`  AS SELECT `p`.`id` AS `id`, `p`.`nomor_sewa` AS `nomor_sewa`, `p`.`status` AS `status`, `p`.`tanggal_mulai` AS `tanggal_mulai`, `p`.`tanggal_selesai` AS `tanggal_selesai`, `p`.`tanggal_kembali_aktual` AS `tanggal_kembali_aktual`, `p`.`sudah_diambil` AS `sudah_diambil`, `p`.`total_harga` AS `total_harga`, `p`.`denda_waktu` AS `denda_waktu`, `p`.`biaya_kerusakan` AS `biaya_kerusakan`, `p`.`grand_total` AS `grand_total`, `p`.`diproses_oleh` AS `diproses_oleh`, `p`.`dikembalikan_oleh` AS `dikembalikan_oleh`, `k`.`nama_lengkap` AS `konsumen`, `k`.`no_whatsapp` AS `no_whatsapp`, `m`.`kode` AS `kode_motor`, `m`.`model` AS `model`, `m`.`warna` AS `warna`, `m`.`plat_nomor` AS `plat_nomor` FROM ((`penyewaan` `p` join `konsumen` `k` on(`k`.`id` = `p`.`konsumen_id`)) join `motor` `m` on(`m`.`id` = `p`.`motor_id`)) ORDER BY `p`.`created_at` DESC ;

-- --------------------------------------------------------

--
-- Struktur untuk view `v_status_armada`
--
DROP TABLE IF EXISTS `v_status_armada`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_status_armada`  AS SELECT `m`.`kode` AS `kode`, `m`.`model` AS `model`, `m`.`warna` AS `warna`, `m`.`plat_nomor` AS `plat_nomor`, `m`.`tarif_weekday` AS `tarif_weekday`, `m`.`tarif_weekend` AS `tarif_weekend`, coalesce(`m`.`status_override`,case when `p`.`id` is null then 'OFTR' when `p`.`sudah_diambil` = 1 then 'ONTR' else 'OTRB' end) AS `status_efektif`, `m`.`status_override` AS `status_override`, `p`.`nomor_sewa` AS `sedang_disewa_nomor`, `k`.`nama_lengkap` AS `disewa_oleh`, `p`.`tanggal_selesai` AS `tenggat` FROM ((`motor` `m` left join `penyewaan` `p` on(`p`.`motor_id` = `m`.`id` and `p`.`status` = 'Aktif' and current_timestamp() between `p`.`tanggal_mulai` and `p`.`tanggal_selesai`)) left join `konsumen` `k` on(`k`.`id` = `p`.`konsumen_id`)) ORDER BY `m`.`model` ASC, `m`.`kode` ASC ;

